export function getTemplateConfig(id: string): BoxTemplateConfig | undefined {
  return TEMPLATE_REGISTRY.find(t => t.id === id);
}

export function listTemplates(): { id: string; name: string; catalog: string }[] {
  return TEMPLATE_REGISTRY.map(t => ({ id: t.id, name: t.name, catalog: t.catalog }));
}